class DeleteMetadataStatement extends PDOStatement {
 private string $sql;private $value;
 public function __construct(string $sql){$this->sql=$sql;}
 public function execute(?array $params=null):bool {
  if (!in_array($params[0] ?? '', ['services','team_members'],true)) throw new RuntimeException('unexpected table');
